async function workbenchStudio(p){
 p.innerHTML=`<div class="studio-banner"><div class="eyebrow">AXIS / AI DEVELOPER</div><h2>${tr('Develop and review projects','طوّر وراجع مشاريعك')}</h2><p>${tr('Private source search, explicit AI context, editable HTML proposals and revision history.','بحث خاص داخل الملفات، سياق تختاره للذكاء الاصطناعي، تطبيقات HTML قابلة للتحرير وسجل للإصدارات.')}</p></div><div class="card"><label>${tr('Project','المشروع')}<select id="wb-project"><option value="">${tr('Choose','اختر')}</option>${records.filter(x=>x.kind==='project'&&x.status!=='deleted').map(x=>`<option value="${esc(x.id)}">${esc(localized(x,'title'))}</option>`).join('')}</select></label><p id="wb-inventory"></p><label>${tr('Text source','ملف نصي')}<select id="wb-file"></select></label><button id="wb-read">${tr('Read excerpt privately','اقرأ مقتطفًا خاصًا')}</button><label>${tr('Search inside project files','ابحث داخل ملفات المشروع')}<input id="wb-query" maxlength="120"></label><button id="wb-search">${tr('Search locally','بحث محلي')}</button><pre id="wb-results"></pre><label>${tr('Context to share with AI (review and edit first)','السياق الذي ستشاركه مع الذكاء الاصطناعي (راجعه أولًا)')}<textarea id="wb-context" rows="8" maxlength="20000" dir="auto"></textarea></label><label>${tr('Persistent private project notes','ذاكرة وملاحظات المشروع الخاصة')}<textarea id="wb-notes" maxlength="8000" rows="5"></textarea></label><label>${tr('Request','طلب التطوير')}<textarea id="wb-prompt" maxlength="4000" rows="4"></textarea></label><div class="toolbar"><button id="wb-review">${tr('Analyze and make a plan','حلّل واقترح خطة')}</button><button id="wb-build" class="primary">${tr('Generate standalone UI','أنشئ واجهة مستقلة')}</button></div><label>${tr('Proposal / review','الاقتراح والمراجعة')}<textarea id="wb-summary" rows="6" maxlength="8000"></textarea></label><label>${tr('Editable standalone HTML','كود HTML قابل للتحرير')}<textarea id="wb-html" rows="18" maxlength="180000" dir="ltr" spellcheck="false"></textarea></label><div class="toolbar"><button id="wb-check">${tr('Static checks','فحص الكود الثابت')}</button><button id="wb-preview">${tr('Run isolated preview','شغّل معاينة معزولة')}</button><button id="wb-save">${tr('Save private version','احفظ إصدارًا خاصًا')}</button><button id="wb-stage">${tr('Transfer to Intelligent Studio draft','انقل إلى مسودة الاستوديو')}</button></div><p>${tr('Generated code is not automatically trusted or tested. Review it before running; never use confidential input in generated apps.','الكود المولّد ليس موثوقًا أو مختبرًا تلقائيًا. راجعه قبل التشغيل ولا تدخل بيانات سرية في هذه التطبيقات.')}</p><label>${tr('Previous versions','الإصدارات السابقة')}<select id="wb-history"></select></label><button id="wb-restore">${tr('Restore as new version','استعادة كإصدار جديد')}</button><p id="wb-status" role="status"></p></div><div id="wb-live" class="card ix-studio"></div>`;
 const $=k=>p.querySelector('#wb-'+k),project=$('project'),status=$('status');let id='',revision='0',busy=false;
 const request=(action,data={})=>api('workbench',{id,action,...data});
 function render(w){revision=w.revision;$('notes').value=w.notes||'';$('html').value=w.html||'';$('summary').value=w.summary||'';$('history').replaceChildren(new Option(tr('Choose version','اختر إصدارًا'),''),...w.history.map(x=>new Option(x.created+' · '+x.revision.slice(0,8),x.revision)));}
 function action(name,fn){$(name).onclick=async()=>{if(busy)return;if(!id){status.textContent=tr('Choose a project','اختر مشروعًا');return}busy=true;const controls=[...p.querySelectorAll('button,select')];controls.forEach(x=>x.disabled=true);try{await fn()}catch(e){status.textContent=e.message}finally{busy=false;controls.forEach(x=>x.disabled=false)}}}
 project.onchange=async()=>{id='';const val=project.value;$('context').value=$('prompt').value=$('results').textContent='';$('live').replaceChildren();render({revision:'0',history:[]});$('file').replaceChildren();$('inventory').textContent='';if(!val)return;try{const v=await api('workbench?id='+encodeURIComponent(val));if(project.value!==val)return;id=val;render(v.workspace);$('inventory').textContent=v.files.length+' '+tr('files','ملف')+' · '+Object.entries(v.files.reduce((a,f)=>(a[f.type]=(a[f.type]||0)+1,a),{})).map(([k,n])=>k+': '+n).join(' / ');$('file').replaceChildren(new Option(tr('Choose source','اختر الملف'),''),...v.files.filter(f=>f.readable).map(f=>new Option(f.path,f.path)));status.textContent=tr('Private workspace loaded','تم تحميل مساحة المشروع الخاصة')}catch(e){status.textContent=e.message}};
 action('read',async()=>{const v=await request('read',{path:$('file').value});$('results').textContent=v.text;status.textContent=v.truncated?tr('Excerpt truncated; no data sent','المقتطف محدود؛ لم ترسل البيانات'):tr('Read locally; no data sent','قراءة محلية؛ لم ترسل البيانات');if(confirm(tr('Copy this excerpt into the editable AI context? It will not be sent until separately approved.','نسخ المقتطف إلى سياق الذكاء الاصطناعي القابل للتحرير؟ لن يُرسل إلا بعد موافقة منفصلة.')))$('context').value=v.text;});
 action('search',async()=>{const v=await request('search',{query:$('query').value});$('results').textContent=v.matches.map(x=>x.path+':'+x.line+' · '+x.excerpt).join('\n')||tr('No matches','لا توجد نتائج');status.textContent=tr('Local search only','بحث محلي فقط')});
 for(const mode of ['review','build'])action(mode,async()=>{if(!confirm(tr('Send the exact request, editable context and private notes above to the configured AI provider? Remove sensitive data first.','إرسال الطلب والسياق القابل للتحرير والملاحظات أعلاه إلى مزود الذكاء الاصطناعي؟ احذف البيانات السرية أولًا.')))return;status.textContent=tr('Generating proposal…','جارٍ تجهيز الاقتراح…');const v=await request('generate',{mode,share:true,prompt:$('prompt').value,context:$('context').value,notes:$('notes').value,language:ar?'ar':'en'});$('summary').value=[v.summary,...v.steps.map(x=>'• '+x)].join('\n');if(v.html)$('html').value=v.html;status.textContent=v.check&&!v.check.ok?v.check.issues.join(' / '):tr('Proposal ready; not executed or saved','الاقتراح جاهز؛ لم يُشغّل أو يُحفظ')});
 async function check(){const v=await request('check',{html:$('html').value});status.textContent=v.ok?tr('Static checks passed; not a security guarantee','نجح الفحص الثابت؛ ليس ضمانًا أمنيًا'):v.issues.join(' / ');return v.ok}
 action('check',check);action('preview',async()=>{if(!await check())return;if(!confirm(tr('Run reviewed HTML in an isolated frame?','تشغيل HTML الذي راجعته في إطار معزول؟')))return;mountStudio($('live'),{mode:'html',title_ar:'معاينة التطبيق',title_en:'Application preview',html:$('html').value},ar)});
 action('save',async()=>{if(!confirm(tr('Save private notes and code version?','حفظ الملاحظات وإصدار الكود بشكل خاص؟')))return;const v=await request('save',{base:revision,notes:$('notes').value,summary:$('summary').value,html:$('html').value,confirm:true});render(v.workspace);status.textContent=tr('Private version saved','تم حفظ الإصدار الخاص')});
 action('restore',async()=>{if(!confirm(tr('Restore this version? Unsaved changes will be lost.','استعادة الإصدار؟ ستفقد التغييرات غير المحفوظة.')))return;const v=await request('restore',{base:revision,revision:$('history').value,confirm:true});render(v.workspace);status.textContent=tr('Restored privately','تمت الاستعادة بشكل خاص')});
 action('stage',async()=>{if(!await check())return;if(!confirm(tr('Replace the saved Studio draft for this project? The approved public version will not change.','استبدال مسودة الاستوديو لهذا المشروع؟ لن تتغير النسخة العامة المعتمدة.')))return;await request('stage',{html:$('html').value,confirm:true});status.textContent=tr('Private draft staged. Open Intelligent Studio to review and publish.','تم تجهيز مسودة خاصة. افتح استوديو التجارب لمراجعتها واعتمادها ونشرها.')});
}

async function connectAdmin(p){try{const site=contactSettings(await api('site'));const active=records.filter(x=>x.kind==='inquiry'&&!['archived','deleted'].includes(x.status)),counts=['new','under_review','approved','completed'];p.innerHTML=`<div class="studio-banner"><div class="eyebrow">IBRAXIS / CONNECT</div><h2>${tr('Contact & business center','مركز التواصل والأعمال')}</h2><p>${tr('Configure public channels and manage private project requests.','اضبط وسائل التواصل العامة وأدر طلبات المشاريع بشكل خاص.')}</p></div><form id="connect-settings" class="card"><h3>${tr('Public contact settings','إعدادات التواصل العامة')}</h3><p class="muted">${tr('Numbers, links and email entered here are public. Leave blank to remove a channel.','أي رقم أو بريد أو رابط تدخله هنا سيصبح عامًا. اترك الحقل فارغًا لإزالة الوسيلة.')}</p><label>${tr('WhatsApp number with country code','رقم واتساب بكود الدولة')}<input dir="ltr" type="tel" name="contact_whatsapp" placeholder="+201XXXXXXXXX" value="${esc(site.contact_whatsapp)}" maxlength="40"></label><label>${tr('Floating WhatsApp icon','أيقونة واتساب العائمة')}<select name="contact_float"><option value="off" ${site.contact_float==='off'?'selected':''}>${tr('Hidden','مخفية')}</option><option value="on" ${site.contact_float==='on'?'selected':''}>${tr('Show on public pages','إظهار في الصفحات العامة')}</option></select></label><label>${tr('Public contact email','البريد العام للتواصل')}<input type="email" name="contact_email" value="${esc(site.contact_email)}" maxlength="160"></label><label>${tr('Booking link (optional, HTTPS)','رابط حجز الاستشارات (اختياري)')}<input type="url" name="contact_booking" value="${esc(site.contact_booking)}" maxlength="500"></label>${['ar','en'].map(l=>`<label>${tr('WhatsApp greeting','رسالة واتساب الجاهزة')} (${l})<input name="contact_message_${l}" maxlength="240" value="${esc(site['contact_message_'+l])}"></label>`).join('')}<button class="primary">${tr('Save contact settings','حفظ إعدادات التواصل')}</button><p id="connect-save-status" role="status"></p></form><section class="card"><h3>${tr('Private inquiry inbox','صندوق الطلبات الخاص')}</h3><div class="ix-business-grid">${counts.map((k,i)=>`<article class="card"><small>${[tr('New','جديد'),tr('Under review','قيد الدراسة'),tr('Approved','معتمد'),tr('Completed','مكتمل')][i]}</small><h2>${active.filter(x=>x.status===k).length}</h2></article>`).join('')}</div><p>${tr('Messages sent via WhatsApp or email can be registered here manually.','يمكن تسجيل الطلبات الواردة من واتساب أو البريد يدويًا هنا.')}</p><form id="connect-inbox"><label>${tr('Request title','عنوان الطلب')}<input name="title" required maxlength="150"></label><label>${tr('Request details (private)','تفاصيل الطلب الخاصة')}<textarea name="body" required maxlength="5000"></textarea></label><button>${tr('Register private request','تسجيل طلب خاص')}</button></form><div class="ix-business-tools"><button id="connect-open-inquiries">${tr('Manage inquiries','إدارة الطلبات')}</button><button id="connect-open-proposals">${tr('Manage proposals','إدارة عروض الأسعار')}</button><button id="connect-open-clients">${tr('Manage clients','إدارة العملاء')}</button><button id="connect-open-agreements">${tr('Manage agreements','إدارة العقود')}</button><button id="connect-open-tasks">${tr('Manage tasks','إدارة المهام')}</button><button id="connect-open-services">${tr('Manage public services','إدارة الخدمات العامة')}</button></div></section><section class="card"><h3>${tr('AI business review','دراسة الطلب بالذكاء الاصطناعي')}</h3><p>${tr('Review only the brief you choose to share. Estimates are not commitments.','راجع فقط تفاصيل الطلب التي تختار مشاركتها. التقديرات ليست التزامًا.')}</p><label>${tr('Choose a private inquiry','اختر طلبًا خاصًا')}<select id="business-source"><option value="">${tr('Select or paste below','اختر أو الصق التفاصيل أدناه')}</option>${active.map(x=>`<option value="${esc(x.id)}">${esc(x.title)}</option>`).join('')}</select></label><label>${tr('Editable AI context — remove personal and confidential details','سياق قابل للتعديل — احذف البيانات الشخصية والسرية')}<textarea id="business-context" maxlength="6000" rows="6"></textarea></label><div class="ix-business-tools"><button id="business-analyze" class="primary">${tr('Generate AI review','جهّز دراسة بالذكاء الاصطناعي')}</button><button id="business-local" type="button">${tr('Prepare offline draft (no AI)','جهّز مسودة محلية (بدون AI)')}</button></div><label>${tr('Editable proposal and analysis','عرض السعر والدراسة (قابلان للتعديل)')}<textarea id="business-output" maxlength="30000" rows="10"></textarea></label><label>${tr('Proposal title','عنوان عرض السعر')}<input id="business-title" maxlength="150"></label><div class="ix-business-tools"><button id="business-save">${tr('Save private proposal','حفظ عرض خاص')}</button><button id="business-print">${tr('Print / save PDF','طباعة / حفظ PDF')}</button></div><p id="business-status" role="status"></p></section>`;
 const $=id=>p.querySelector('#'+id),form=$('connect-settings');form.onsubmit=async e=>{e.preventDefault();if(!confirm(tr('Save these public contact details? Publish separately when ready.','حفظ وسائل التواصل العامة؟ انشرها لاحقًا عندما تصبح جاهزة.')))return;try{const v=await api('site',Object.fromEntries(new FormData(form)));form.elements.contact_whatsapp.value=v.contact_whatsapp;form.elements.contact_float.value=v.contact_float;$('connect-save-status').textContent=tr('Saved. Use Smart Publishing to update all public pages.','تم الحفظ. استخدم النشر الذكي لتحديث الصفحات العامة.')}catch(e){$('connect-save-status').textContent=e.message}};
 $('connect-inbox').onsubmit=async e=>{e.preventDefault();try{await api('records',{...Object.fromEntries(new FormData(e.target)),kind:'inquiry',brand:'personal',status:'new'});records=await api('records');await connectAdmin(p);msg(tr('Private inquiry registered','تم تسجيل الطلب الخاص'))}catch(e){msg(e)}};
 for(const k of ['inquiries','proposals','clients','agreements','tasks','services'])$('connect-open-'+k).onclick=()=>{selected={inquiries:'inquiry',proposals:'proposal',clients:'client',agreements:'agreement',tasks:'task',services:'service'}[k];dashboard()};
 $('business-source').onchange=()=>{const r=active.find(x=>x.id===$('business-source').value);if(!r)return;let value=r.body;try{const j=JSON.parse(value);if(typeof j.message==='string')value=[j.kind,j.budget,j.timeline,j.message].filter(Boolean).join('\n')}catch{}$('business-context').value=(r.title+'\n'+value).slice(0,6000);$('business-title').value=r.title.slice(0,150)};
 const fillReview=v=>{$('business-output').value=Object.entries(v).map(([k,v])=>({summary:tr('Summary','الملخص'),feasibility:tr('Feasibility','الجدوى'),scope:tr('Scope','النطاق'),timeline:tr('Timeline','المدة'),budget:tr('Budget estimate','تقدير الميزانية'),questions:tr('Questions','الأسئلة'),proposal:tr('Proposal','عرض السعر')}[k]+':\n'+v)).join('\n\n').slice(0,30000)};$('business-local').onclick=()=>{try{fillReview(localBusinessDraft($('business-context').value,ar));$('business-status').textContent=tr('Offline draft ready (not AI-generated). Review before saving.','المسودة المحلية جاهزة (ليست دراسة AI). راجعها قبل الحفظ.')}catch(e){$('business-status').textContent=e.message}};
 $('business-analyze').onclick=async()=>{const context=$('business-context').value;if(!context.trim()||!confirm(tr('Send exactly the edited context to the configured AI provider?','إرسال هذا السياق المعدّل تحديدًا إلى مزود الذكاء الاصطناعي؟')))return;const b=$('business-analyze');b.disabled=true;$('business-status').textContent=tr('Generating your private review…','جارٍ تجهيز الدراسة الخاصة…');try{const v=await api('business/analyze',{context,language:ar?'ar':'en',share:true});fillReview(v);$('business-status').textContent=tr('Review ready; not saved or sent to the client','الدراسة جاهزة؛ لم تحفظ أو ترسل للعميل')}catch(e){$('business-status').textContent=e.message||tr('Unable to generate a review. Please try again.','تعذّر تجهيز الدراسة، أعد المحاولة.')}finally{b.disabled=false}};
 $('business-save').onclick=async()=>{const title=$('business-title').value,body=$('business-output').value;if(!title.trim()||!body.trim()||!confirm(tr('Save this as a private proposal draft?','حفظ هذا العرض كمسودة خاصة؟')))return;try{await api('records',{kind:'proposal',brand:'personal',title,body,status:'draft'});records=await api('records');$('business-status').textContent=tr('Private proposal saved','تم حفظ العرض الخاص')}catch(e){$('business-status').textContent=e.message}};
 $('business-print').onclick=()=>{if(!$('business-output').value.trim())return;if(!confirm(tr('Print only the reviewed proposal text?','طباعة نص العرض الذي راجعته فقط؟')))return;const n=document.createElement('article');n.id='ix-print-copy';n.textContent=$('business-title').value+'\n\n'+$('business-output').value;n.hidden=true;document.body.append(n);document.body.classList.add('ix-print-proposal');n.hidden=false;try{window.print()}finally{n.remove();document.body.classList.remove('ix-print-proposal')}};
 }catch(e){p.textContent=e.message}}
